<?php
require_once '../../middleware/jsonMiddleware.php';require_once '../../middleware/requestLogger.php';require_once '../../middleware/corsMiddleware.php';require_once '../../middleware/authMiddleware.php';require_once '../../utils/response.php';require_once '../../config/database.php';
use MongoDB\BSON\ObjectId;use MongoDB\BSON\UTCDateTime;
setJsonResponse();handleCors();logRequest();requireLogin();if($_SERVER['REQUEST_METHOD']!=='POST')sendResponse(false,'Method not allowed. Use POST.',null,405);
$data=json_decode(file_get_contents('php://input'),true);$vehicleId=trim($data['vehicleId']??'');$startText=trim($data['startDate']??'');$endText=trim($data['endDate']??'');if(!preg_match('/^[a-f0-9]{24}$/i',$vehicleId))sendResponse(false,'Invalid vehicle ID.',null,400);
$start=DateTimeImmutable::createFromFormat('!Y-m-d',$startText);$end=DateTimeImmutable::createFromFormat('!Y-m-d',$endText);$today=new DateTimeImmutable('today');if(!$start||!$end)sendResponse(false,'Please select valid dates.',null,400);if($start<$today)sendResponse(false,'Pickup date cannot be in the past.',null,400);if($end<$start)sendResponse(false,'Return date cannot be before pickup date.',null,400);
try{$db=getDatabase();$vid=new ObjectId($vehicleId);$vehicle=$db->vehicles->findOne(['_id'=>$vid]);if(!$vehicle)sendResponse(false,'Vehicle not found.',null,404);if(($vehicle['status']??'')!=='Available')sendResponse(false,'Vehicle is currently unavailable.',null,409);$startUtc=new UTCDateTime($start->getTimestamp()*1000);$endUtc=new UTCDateTime($end->getTimestamp()*1000);
$blocked=$db->bookings->findOne(['vehicleId'=>$vid,'status'=>['$in'=>['Approved','Confirmed']],'startDate'=>['$lte'=>$endUtc],'endDate'=>['$gte'=>$startUtc]]);if($blocked)sendResponse(false,'These dates are already reserved. Please choose different dates.',null,409);
$days=(int)$start->diff($end)->days+1;$price=(float)($vehicle['pricePerDay']??0);$total=$days*$price;$result=$db->bookings->insertOne(['userId'=>new ObjectId($_SESSION['user_id']),'vehicleId'=>$vid,'vehicleName'=>(string)$vehicle['name'],'vehicleType'=>(string)($vehicle['type']??''),'pricePerDay'=>$price,'startDate'=>$startUtc,'endDate'=>$endUtc,'totalDays'=>$days,'totalPrice'=>$total,'status'=>'Pending','paymentStatus'=>'Not Paid','createdAt'=>new UTCDateTime()]);sendResponse(true,'Booking request sent. Waiting for admin approval.',['bookingId'=>(string)$result->getInsertedId()],201);}catch(Exception $e){error_log('Booking error: '.$e->getMessage());sendResponse(false,'Booking request failed.',null,500);}
